  a0 = Z_to_bv 64 fd -> a2 = Z_to_bv 64 count ->
  (3 <= fd < 2^32)%Z -> (1 <= count <= 16777216)%Z ->
  (0x60d000 <= bv_unsigned a1 \/ (0x5d9fd0 <= bv_unsigned a1 /\ bv_unsigned a1 + count <= 0x5e9fd0 /\ bv_unsigned a1 + count <= errno_addr tp))%Z -> (bv_unsigned a1 + count <= lo)%Z ->
  (0xb8b80 <= errno_addr tp /\ errno_addr tp + 4 <= 0x60d000)%Z -> (164 <= bv_unsigned tp)%Z ->
